UPDATE public.inspection_base_items SET text = '17.2.9.1 엘리베이터 및 조명의 전원공급시스템은 주 전원공급장치 및 보조(비상, 대기 또는 대체) 전원공급장치로 구성되어야 한다. 방화등급은 엘리베이터 승강로에 주어진 등급과 동등 이상이어야 한다.(그림 29 참조)', section_title = '17.2.9.1 엘리베이터 및 조명의 전원공급시스템은 주 전원공급장치 및 보조(비상, 대기 또는 대체) 전원공급장치로 구성되어야 한다. 방화등급은 엘리베이터 승강로에 주어진 등급과 동등 이상이어야 한다.(그림 29 참조)', updated_at = now() WHERE item_id = '17.2.9.1';
INSERT INTO public.inspection_base_items (item_id, section_id, section_title, parent_section_id, text, sort_order, is_active) VALUES ('17.2.9.2.1', '17', '17.2.9.2.1 보조 전원공급장치는 자가발전기에 교류예비전원으로서 다른 용도의 급전용량과는 별도로 소방구조용 엘리베이터의 전 대수를 동시에 운행시킬 수 있는 충분한 전력용량이 확보되어야 한다. 다만, 2곳 이상의 변전소(전기설비기술기준에관한규칙 제2조제2호의 규정에 의한 변전소)로부터 전력을 동시에 공급받는 경우 또는 1곳의 변전소로부', '17.2.9.2', '17.2.9.2.1 보조 전원공급장치는 자가발전기에 교류예비전원으로서 다른 용도의 급전용량과는 별도로 소방구조용 엘리베이터의 전 대수를 동시에 운행시킬 수 있는 충분한 전력용량이 확보되어야 한다. 다만, 2곳 이상의 변전소(전기설비기술기준에관한규칙 제2조제2호의 규정에 의한 변전소)로부터 전력을 동시에 공급받는 경우 또는 1곳의 변전소로부터 전력의 공급이 중단될 때 자동으로 다른 변전소의 전원을 공급받을 수 있도록 되어 있는 경우 이 전력용량이 소방구조용 엘리베이터의 전부를 동시에 운행시킬 수 있도록 충분한 전력용량이 공급될 경우 자가발전기는 설치되지 않아도 된다.', 172093, 'true') ON CONFLICT (item_id) DO UPDATE SET text = EXCLUDED.text, section_title = EXCLUDED.section_title, updated_at = now();
INSERT INTO public.inspection_base_items (item_id, section_id, section_title, parent_section_id, text, sort_order, is_active) VALUES ('17.2.9.2.2', '17', '17.2.9.2.2 공동주택단지에 있어서 단지 내 소방구조용 엘리베이터의 전 대수를 동시에 운행시킬 수 있는 충분한 전력용량을 확보하기 어려운 경우에는 각 동마다 설치된 소방구조용 엘리베이터의 전 대수를 동시에 운행시킬 수 있는 충분한 전력용량을 다른 용도의 급전용량과는 별도로 확보해야 하며, 각 동마다 개별급전이 가능하도록 절환장치가 설', '17.2.9.2', '17.2.9.2.2 공동주택단지에 있어서 단지 내 소방구조용 엘리베이터의 전 대수를 동시에 운행시킬 수 있는 충분한 전력용량을 확보하기 어려운 경우에는 각 동마다 설치된 소방구조용 엘리베이터의 전 대수를 동시에 운행시킬 수 있는 충분한 전력용량을 다른 용도의 급전용량과는 별도로 확보해야 하며, 각 동마다 개별급전이 가능하도록 절환장치가 설치되어야 한다.', 172094, 'true') ON CONFLICT (item_id) DO UPDATE SET text = EXCLUDED.text, section_title = EXCLUDED.section_title, updated_at = now();
INSERT INTO public.inspection_base_items (item_id, section_id, section_title, parent_section_id, text, sort_order, is_active) VALUES ('17.2.9.2.3', '17', '17.2.9.2.3 정전시에는 보조 전원공급장치에 의하여 엘리베이터를 다음과 같이 운행시킬 수 있어야 하다.', '17.2.9.2', '17.2.9.2.3 정전시에는 보조 전원공급장치에 의하여 엘리베이터를 다음과 같이 운행시킬 수 있어야 하다.
가) 60초 이내에 엘리베이터 운행에 필요한 전력용량을 자동으로 발생시키도록 하되 수동으로 전원을 작동시킬 수 있어야 한다.
나) 2시간 이상 운행시킬 수 있어야 한다.', 172095, 'true') ON CONFLICT (item_id) DO UPDATE SET text = EXCLUDED.text, section_title = EXCLUDED.section_title, updated_at = now();
